'use strict';
// references/catalog.md is generated by scripts/catalog.js. A hand edit or a runtime change without a
// regenerate makes the AI use names the engine does not accept, so regenerate in a copy and compare.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { SKILL, run, makeTmp, rmTmp, readNormalised } = require('./helpers');

test('committed catalog.md equals a fresh run of scripts/catalog.js', () => {
  const tmp = makeTmp('catalog');
  try {
    // catalog.js writes ../references/catalog.md relative to itself, so the copy is self-contained
    const copy = path.join(tmp, 'explainimals');
    fs.cpSync(SKILL, copy, { recursive: true });
    const r = run([path.join(copy, 'scripts', 'catalog.js')], { cwd: copy });
    assert.equal(r.status, 0, `catalog.js exited ${r.status}: ${r.output}`);

    const fresh = readNormalised(path.join(copy, 'references', 'catalog.md'));
    const committed = readNormalised(path.join(SKILL, 'references', 'catalog.md'));
    assert.equal(committed, fresh, 'catalog.md is stale: run node plugin/skills/explainimals/scripts/catalog.js');
  } finally {
    rmTmp(tmp);
  }
});
